#ifndef GUARD_CONSTANTS_ACTORS_H
#define GUARD_CONSTANTS_ACTORS_H

/*
 * Actor kinds (#155 run 6, the owner's decision D6). Task.actorKind is the
 * kind CreateActorByKind (src/actor_63698.c) creates an actor as: the kind
 * picks the task-type table its subtype indexes, and the actor core branches
 * on it. Generated by tools/constants.py; each define is logged with its
 * evidence in docs/analysis/constants.csv.
 */

/* Actor kinds - Task.actorKind: the kind CreateActor stores and CreateActorByKind / ActorBindDefSlot pick the subtype's task-type and ActorDef tables by (src/actor_63698.c) */
#define ACTOR_KIND_ENEMY                0
#define ACTOR_KIND_MID_BOSS             1
#define ACTOR_KIND_BOSS                 2
#define ACTOR_KIND_CHILD                4 /* an actor spawned by another actor from an ActorSpawn record */
#define ACTOR_KIND_OBJECT               5 /* the stage objects */
#define ACTOR_KIND_ITEM                 6 /* the items */
#define ACTOR_KIND_BOSS_CHILD_TASK      7 /* a task (no Actor) of a boss */
#define ACTOR_KIND_MID_BOSS_CHILD_TASK  8 /* a task (no Actor) of a mid-boss */

#endif // GUARD_CONSTANTS_ACTORS_H
